      description: "Leverandørkostnad",
      date: TODAY,
      count: 1,
      unitCostCurrency: SUPP_COST,
      isChargeable: false,
    }),
  ]);
  const sId = supp.value.id;

  console.log("STEP 4 done:", { timesheetEntries: ts.values?.length, sId });

